// ❌ OLD: Required forwardRef wrapper and manual null-checking in callback ref
import { forwardRef } from 'react';

const CustomInput = forwardRef(function CustomInput(props, ref) {
  return <input ref={ref} {...props} />;
});

export default function App() {
  return (
    <CustomInput
      ref={(node) => {
        if (node) {
          console.log('Attached:', node);
        } else {
          console.log('Detached (manual null check)');
        }
      }}
    />
  );
}

// ✅ NEW: ref is a standard prop. Callback ref returns cleanup function.
function CustomInput({ ref, ...props }) {
  return <input ref={ref} {...props} />;
}

export default function App() {
  return (
    <CustomInput
      ref={(node) => {
        const observer = new ResizeObserver(() => console.log('Resized'));
        observer.observe(node);

        // ✅ NEW: Return cleanup directly! Runs automatically on unmount
        return () => {
          observer.disconnect();
        };
      }}
    />
  );
}
